/**
 * Render an invoice as plain text for display to customers.
 * @param {object} invoice
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  const customerResult = getCustomer(invoice.customerId);
  const customerName = customerResult.ok ? customerResult.value.name : 'Unknown Customer';

  const numberLine = invoice.number ? invoice.number : 'DRAFT';
  const customerLine = customerName;

  const lineTexts = [];
  for (const line of invoice.lines) {
    const total = lineTotal(line);
    lineTexts.push(`${line.qty}x ${line.name} @ ${formatEuros(line.unitPrice)} = ${formatEuros(total)}`);

    const discount = lineDiscount(line);
    if (discount > 0) {
      lineTexts.push(`  Discount: -${formatEuros(discount)}`);
    }
  }

  const totals = invoiceTotals(invoice);
  const summaryLines = [];
  summaryLines.push(`Subtotal: ${formatEuros(totals.subtotal)}`);
  if (totals.discount > 0) {
    summaryLines.push(`Discount: -${formatEuros(totals.discount)}`);
  }
  if (totals.vat > 0) {
    summaryLines.push(`VAT: ${formatEuros(totals.vat)}`);
  }
  if (invoice.voucher) {
    summaryLines.push(`Voucher (${invoice.voucher.code}): -${formatEuros(invoice.voucher.amount)}`);
  }
  summaryLines.push(`Total: ${formatEuros(totals.total)}`);

  if (invoice.dueDate) {
    summaryLines.push(`Due: ${invoice.dueDate}`);
  }

  if (invoice.paid && invoice.paid > 0) {
    summaryLines.push(`Paid: ${formatEuros(invoice.paid)}`);
  }

  const allLines = [numberLine, customerLine, ...lineTexts, ...summaryLines];
  return allLines.join('\n');
}

