    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value;

    const withDueDate = {
      ...invoice,
      dueDate: '2026-11-07',
    };

    const text = renderInvoiceText(withDueDate);

    assert.match(text, /Due: 2026-11-07/);
  });

