      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 2 }],
    }).value;

    const text = renderInvoiceText(invoice);
    const lines = text.split('\n');

    // Second line after number and customer
    assert.equal(lines[2], '2x Design work (hour) @ €85.00 = €170.00');
  });

  test('formats multiple lines', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [
        { sku: 'DES-HOUR', qty: 1 },
        { sku: 'DEV-HOUR', qty: 2 },
      ],
    }).value;

    const text = renderInvoiceText(invoice);

    assert.match(text, /1x Design work \(hour\) @ €85.00 = €85.00/);
    assert.match(text, /2x Development \(hour\) @ €95.00 = €190.00/);
  });

  test('includes total line with VAT', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 2 }],
    }).value;

    const text = renderInvoiceText(invoice);
    const lines = text.split('\n');

    // Should have Subtotal, Discount, VAT, and Total lines
    const lastLine = lines[lines.length - 1];
    assert.match(lastLine, /^Total:/);
  });

  test('calculates correct total for multiple lines', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [
        { sku: 'DES-HOUR', qty: 2 },
        { sku: 'DEV-HOUR', qty: 1 },
      ],
    }).value;

    const text = renderInvoiceText(invoice);
    const lines = text.split('\n');

    // Should end with Total line
    const lastLine = lines[lines.length - 1];
    assert.match(lastLine, /^Total:/);
  });

  test('has correct line count', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [
        { sku: 'DES-HOUR', qty: 1 },
        { sku: 'DEV-HOUR', qty: 1 },
        { sku: 'COPY-HOUR', qty: 1 },
      ],
    }).value;

