import { test, describe } from 'node:test';
import assert from 'node:assert/strict';
import { renderInvoiceText } from '../src/render.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { TIER_DISCOUNTS } from '../src/customers.js';

describe('renderInvoiceText', () => {
  test('renders draft invoice with DRAFT label', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value;

    const text = renderInvoiceText(invoice);
    const lines = text.split('\n');

    assert.equal(lines[0], 'DRAFT');
  });

  test('renders issued invoice with invoice number', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value;

    const issued = issueInvoice(invoice, []).value;
    const text = renderInvoiceText(issued);
    const lines = text.split('\n');

    assert.equal(lines[0], 'INV-2026-0001');
  });

  test('includes customer name', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value;

    const text = renderInvoiceText(invoice);
    const lines = text.split('\n');

    assert.equal(lines[1], 'Northwind Studio');
  });

  test('formats single line with qty, name, unit price and total', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 2 }],
    }).value;

    const text = renderInvoiceText(invoice);
    const lines = text.split('\n');

    // Second line after number and customer
    assert.equal(lines[2], '2x Design work (hour) @ €85.00 = €170.00');
  });

  test('formats multiple lines', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [
        { sku: 'DES-HOUR', qty: 1 },
        { sku: 'DEV-HOUR', qty: 2 },
      ],
    }).value;

    const text = renderInvoiceText(invoice);

    assert.match(text, /1x Design work \(hour\) @ €85.00 = €85.00/);
    assert.match(text, /2x Development \(hour\) @ €95.00 = €190.00/);
  });

  test('includes total line with VAT', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 2 }],
    }).value;

    const text = renderInvoiceText(invoice);

    // Should have Subtotal, Discount, VAT, and Total lines
    assert.match(text, /Total:/);
  });

  test('calculates correct total for multiple lines', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [
        { sku: 'DES-HOUR', qty: 2 },
        { sku: 'DEV-HOUR', qty: 1 },
      ],
    }).value;

    const text = renderInvoiceText(invoice);

    // Should have Total line
    assert.match(text, /Total:/);
  });

  test('has correct line count', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [
        { sku: 'DES-HOUR', qty: 1 },
        { sku: 'DEV-HOUR', qty: 1 },
        { sku: 'COPY-HOUR', qty: 1 },
      ],
    }).value;

    const text = renderInvoiceText(invoice);
    const lines = text.split('\n');

    // number + customer + 3 lines + 3 discounts + subtotal + discount + VAT + total + due = 13 lines
    assert.equal(lines.length, 13);
  });

  test('handles large quantities', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 100 }],
    }).value;

    const text = renderInvoiceText(invoice);
    const lines = text.split('\n');

    assert.equal(lines[2], '100x Design work (hour) @ €85.00 = €8,500.00');
  });

  test('handles expensive items with VAT-exempt prices', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
    }).value;

    const text = renderInvoiceText(invoice);

    assert.match(text, /1x Brand workshop \(day, VAT exempt\) @ €600.00 = €600.00/);
    // Should have Total line
    assert.match(text, /Total:/);
  });

  test('renders issued invoice with all data preserved', () => {
    const invoice = createInvoice({
      customerId: 'C-002',
      issueDate: '2025-03-15',
      lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    }).value;

    const issued = issueInvoice(invoice, ['INV-2025-0001']).value;
    const text = renderInvoiceText(issued);
    const lines = text.split('\n');

    assert.equal(lines[0], 'INV-2025-0002');
    assert.equal(lines[1], 'Blue Fern Bakery');
    assert.equal(lines[2], '5x Development (hour) @ €95.00 = €475.00');
    // Last line should be Total
    assert.match(lines[lines.length - 1], /^Total:/);
  });

  test('handles unknown customer gracefully', () => {
    const invoice = {
      customerId: 'UNKNOWN-CUSTOMER',
      issueDate: '2026-10-07',
      status: 'draft',
      lines: [
        {
          sku: 'DES-HOUR',
          name: 'Design work (hour)',
          qty: 1,
          unitPrice: 8500,
          vatRate: 21,
        },
      ],
    };

    const text = renderInvoiceText(invoice);
    const lines = text.split('\n');

    assert.equal(lines[1], 'Unknown Customer');
  });

  test('shows VAT line when VAT is present', () => {
    const invoice = createInvoice({
      customerId: 'C-002',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value;

    const text = renderInvoiceText(invoice);
    const lines = text.split('\n');

    // Should include VAT line (standard tier has 0% discount, so VAT applies to full amount)
    // Line 0: DRAFT
    // Line 1: Blue Fern Bakery (C-002, standard)
    // Line 2: Invoice item
    // Line 3: Subtotal
    // Line 4: VAT (no discount for standard tier)
    // Line 5: Total
    assert.match(text, /VAT:/);
  });

  test('shows discount and VAT lines correctly', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value;

    const text = renderInvoiceText(invoice);

    // Gold tier should have discount
    assert.match(text, /Discount:/);
    // All items have VAT
    assert.match(text, /VAT:/);
    // Should have subtotal and total
    assert.match(text, /Subtotal:/);
    assert.match(text, /Total:/);
  });

  test('shows line-level discount when line has one', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 15 }],
    }).value;

    const text = renderInvoiceText(invoice);

    assert.match(text, /Discount:/);
  });

  test('shows voucher when invoice has one', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value;

    const withVoucher = {
      ...invoice,
      voucher: { code: 'SAVE10', amount: 1000 },
    };

    const text = renderInvoiceText(withVoucher);

    assert.match(text, /Voucher \(SAVE10\):/);
    assert.match(text, /Voucher.*1000/);
  });

  test('shows due date when invoice has one', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value;

    const withDueDate = {
      ...invoice,
      dueDate: '2026-11-07',
    };

    const text = renderInvoiceText(withDueDate);

    assert.match(text, /Due: 2026-11-07/);
  });

  test('shows paid amount when invoice has payments', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value;

    const withPayment = {
      ...invoice,
      paid: 5000,
    };

    const text = renderInvoiceText(withPayment);

    assert.match(text, /Paid:/);
  });

  test('shows all details: discount, voucher, due date, and paid', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 10 }],
    }).value;

    const issued = issueInvoice(invoice, []).value;

    const complete = {
      ...issued,
      voucher: { code: 'SAVE5', amount: 500 },
      dueDate: '2026-11-07',
      paid: 3000,
    };

    const text = renderInvoiceText(complete);

    assert.match(text, /Voucher \(SAVE5\):/);
    assert.match(text, /Due: 2026-11-07/);
    assert.match(text, /Paid:/);
  });

  test('does not show voucher when invoice has none', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value;

    const text = renderInvoiceText(invoice);

    assert.doesNotMatch(text, /Voucher/);
  });

  test('does not show due date when invoice has none', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value;

    const text = renderInvoiceText(invoice);

    assert.doesNotMatch(text, /Due:/);
  });

  test('does not show paid when invoice has no payments', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value;

    const text = renderInvoiceText(invoice);

    assert.doesNotMatch(text, /Paid:/);
  });
});

